    while (current != NULL) {
        if (headers_match(current->headers, headers)) {
            // Update existing device
            current->timestamp = t;

            // Reallocate memory if needed
            size_t new_location_length = strlen(headers_get(headers, "Location")) + 1;
            if (new_location_length > current->location_length) {
                char *new_location = realloc(current->location, new_location_length);
                if (new_location == NULL) {
                    return -1;
                }
                current->location = new_location;
                current->location_length = new_location_length;
            }

            return 0;
        }
        current = current->next;
    }

    // No match found, create new device
    struct device *new_device = malloc(sizeof(struct device));
    if (new_device == NULL) {
        return -1;
    }

    // Copy headers
    new_device->headers = headers_copy(headers);
    if (new_device->headers == NULL) {
        free(new_device);
        return -1;
    }

    // Initialize timestamp
    new_device->timestamp = t;

    // Allocate and copy location header
    const char *location_header = headers_get(headers, "Location");
    new_device->location_length = strlen(location_header) + 1;
    new_device->location = strdup(location_header);
    if (new_device->location == NULL) {
        headers_free(new_device->headers);
        free(new_device);
        return -1;
    }

    // Add to device list
    new_device->next = device_list;
    device_list = new_device;

    // Send notification for new device
    send_notification(new_device);

    return 1;
